/* ============ A6 sentiment ============ */
PAGES.sentiment = () => {
  const head = tbar('情绪与语义', '你的消息 · 中文 62% · 英文 31% · 混合 7%', '<button type="button" class="btn gh" data-act="moodHow">' + ic('info', 14) + '情绪如何计算</button><button type="button" class="btn ai" data-act="phrasesToRule">' + ic('spark', 14) + '把高频纠偏写成规则</button>');
  if (S.engine === 'stats') return head + '<div class="content" id="content">' + empty('语义分析已关闭：分析引擎设为「仅统计」。<br><br><button type="button" class="btn p" data-act="openSettings" data-tab="analysis">去设置开启</button>') + '</div>';
  const L = sel(); const ms = moodSeries(L, S.range); CUR.mood = ms;
  const W = 1000, H = 120, x0 = 34, pw = W - x0 - 6, step = pw / ms.length;
  const X = (i) => x0 + i * step + step / 2, Y = (v) => 60 - v * 54;
  const pts = ms.map((b, i) => b.mood == null ? null : [X(i), Y(b.mood), b.mood]);
  let line = '', pos = '', neg = '', prev = null;
  pts.forEach((p) => { if (!p) return; line += (line ? ' L' : 'M') + p[0].toFixed(1) + ' ' + p[1].toFixed(1); if (prev) { const seg = 'M' + prev[0].toFixed(1) + ' 60L' + prev[0].toFixed(1) + ' ' + prev[1].toFixed(1) + 'L' + p[0].toFixed(1) + ' ' + p[1].toFixed(1) + 'L' + p[0].toFixed(1) + ' 60Z'; if (prev[2] + p[2] >= 0) pos += seg; else neg += seg; } prev = p; });
  const lows = ms.map((b, i) => [b, i]).filter((x) => x[0].mood != null).sort((a, b) => a[0].mood - b[0].mood).slice(0, 2);
  const cmax = Math.max(1, ...ms.map((b) => b.corr));
  let svg = '<line x1="' + x0 + '" x2="' + (W - 6) + '" y1="60" y2="60" stroke="var(--line)"/><line x1="' + x0 + '" x2="' + (W - 6) + '" y1="6" y2="6" stroke="var(--hair)"/><line x1="' + x0 + '" x2="' + (W - 6) + '" y1="114" y2="114" stroke="var(--hair)"/><text x="' + (x0 - 6) + '" y="9">+1</text><text x="' + (x0 - 6) + '" y="63">0</text><text x="' + (x0 - 6) + '" y="117">−1</text>' +
    '<path d="' + (neg || 'M0 0') + '" fill="var(--crit-m)" fill-opacity=".1"/><path d="' + (pos || 'M0 0') + '" fill="var(--ink-3)" fill-opacity=".08"/><path d="' + (line || 'M0 0') + '" fill="none" stroke="var(--ink-1)" stroke-width="2" stroke-linejoin="round"/>';
  lows.forEach((l) => { const b = l[0], i = l[1]; svg += '<circle cx="' + X(i).toFixed(1) + '" cy="' + Y(b.mood).toFixed(1) + '" r="5" fill="var(--crit-m)" stroke="var(--surface)" stroke-width="2"/><text x="' + (X(i) + 8).toFixed(1) + '" y="' + (Y(b.mood) + 16).toFixed(1) + '" font-family="var(--sans)" font-size="11" fill="var(--ink-2)">' + b.lbl + ' · ' + (b.xs.filter((s) => s.corr).length) + ' 个会话有纠偏</text>'; });
  ms.forEach((b, i) => { const h = b.corr / cmax * 34; svg += '<rect x="' + (X(i) - Math.min(7, step * 0.3)).toFixed(1) + '" y="' + (166 - h).toFixed(1) + '" width="' + Math.min(14, step * 0.6).toFixed(1) + '" height="' + Math.max(1, h).toFixed(1) + '" rx="2" fill="' + (b.corr >= cmax * 0.7 ? 'var(--crit-m)' : 'var(--h2)') + '"/><rect x="' + (x0 + i * step).toFixed(1) + '" y="0" width="' + step.toFixed(1) + '" height="168" fill="transparent" data-tf="mood|' + i + '"/>'; });
  svg += '<line x1="' + x0 + '" x2="' + (W - 6) + '" y1="166" y2="166" stroke="var(--line)"/><text x="' + (x0 - 6) + '" y="160">纠偏</text>';
  const every = Math.ceil(ms.length / 6); ms.forEach((b, i) => { if (i % every === 0) svg += '<text x="' + X(i).toFixed(1) + '" y="182" text-anchor="middle">' + b.lbl + '</text>'; });
  const fr = Object.entries(countBy(L, 'fric')).sort((a, b) => b[1] - a[1]); const frMax = Math.max(1, ...fr.map((x) => x[1]));
  const tp = Object.keys(TOPICS).map((k) => { const xs = L.filter((s) => s.topic === k); return { k, n: xs.length, mood: xs.length ? sum(xs, (s) => s.mood) / xs.length : 0 }; }).filter((t) => t.n).sort((a, b) => b.n - a.n);
  const scale = L.length / 186;
  return head + '<div class="content" id="content">' + filterRow('<span class="row cap">' + ic('shield', 13, 'color:var(--good)') + '语义分析由本地 Agent 完成，原文不离开本机</span>') +
    '<div class="stack"><div class="card pad"><div class="hd"><div class="grow"><span class="ct">情绪曲线</span><span class="cap">' + (ms.length > 31 ? '每周' : '每日') + '均值 · −1 沮丧 … +1 满意 · 下方为纠偏次数（同一横轴，单独成图）</span></div></div><svg class="chart" viewBox="0 0 ' + W + ' 188" role="img" aria-label="情绪曲线与纠偏次数">' + svg + '</svg></div>' +
    '<div class="two" style="grid-template-columns:400px minmax(0,1fr)"><div class="card pad"><div class="hd"><div class="grow"><span class="ct">摩擦分类</span><span class="cap">出现该摩擦的会话数 · 点击查看</span></div></div><div class="col" style="gap:6px">' + (fr.length ? fr.map((f, i) => '<button type="button" data-act="fricGo" data-k="' + esc(f[0]) + '" style="display:grid;grid-template-columns:118px minmax(0,1fr) 24px;gap:10px;align-items:center;border:0;background:none;padding:2px 0;text-align:left;width:100%"><span style="font-size:12px;color:var(--ink-2);white-space:nowrap">' + f[0] + '</span><span style="height:10px"><span style="display:block;height:10px;width:' + (f[1] / frMax * 100) + '%;border-radius:0 4px 4px 0;background:' + (i < 2 ? 'var(--ink-1)' : 'var(--h3)') + '"></span></span><span class="mono" style="font-size:11.5px;text-align:right;font-weight:600">' + f[1] + '</span></button>').join('') : '<span class="cap">没有摩擦记录</span>') + '</div><div class="cap" style="font-size:11px;margin-top:8px">前两类占全部摩擦的 ' + (fr.length ? Math.round((fr[0][1] + (fr[1] ? fr[1][1] : 0)) / Math.max(1, sum(fr, (x) => x[1])) * 100) : 0) + '%，都可以用规则前置</div></div>' +
    '<div class="card pad"><div class="hd"><div class="grow"><span class="ct">语义主题</span><span class="cap">按会话意图聚类 · 点击把它设为全局筛选</span></div></div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(190px,100%),1fr));gap:6px">' + tp.map((t, i) => '<button type="button" data-act="topicSet" data-k="' + t.k + '" style="border-radius:9px;border:' + (S.topic === t.k ? '1.5px solid var(--ink-1)' : '1px solid transparent') + ';background:' + (i === 0 ? 'var(--sunken)' : 'var(--bg)') + ';padding:9px 11px;display:flex;flex-direction:column;gap:3px;text-align:left"><b style="font-size:12.5px">' + TOPICS[t.k] + '</b><span class="mono cap" style="font-size:10.5px">' + t.n + ' 个会话 · 平均情绪 ' + (t.mood > 0 ? '+' : '') + f1(t.mood) + '</span><span style="height:4px;border-radius:2px;background:var(--hair);position:relative;margin-top:4px;display:block"><span style="position:absolute;top:-2px;width:8px;height:8px;margin-left:-4px;border-radius:50%;left:' + ((t.mood + 1) / 2 * 100).toFixed(0) + '%;background:' + (t.mood < 0 ? 'var(--crit-m)' : 'var(--ink-1)') + ';box-shadow:0 0 0 2px var(--surface)"></span></span></button>').join('') + '</div></div></div>' +
    '<div class="two" style="grid-template-columns:minmax(0,1fr) minmax(0,1fr)"><div class="card pad"><div class="hd"><div class="grow"><span class="ct">你的高频反馈语</span><span class="cap">已脱敏 · 点击查看出处</span></div></div><div class="row" style="flex-wrap:wrap;gap:6px">' + PHRASES.map((p) => '<button type="button" data-act="phrase" data-k="' + esc(p[0]) + '" style="height:28px;display:inline-flex;align-items:center;gap:6px;padding:0 8px;border-radius:7px;border:1px solid var(--line);background:var(--surface)"><span style="font-size:12px">「' + esc(p[0]) + '」</span><span class="mono cap" style="font-size:10.5px">×' + Math.max(1, Math.round(p[1] * scale)) + '</span><span style="font-size:10.5px;padding:1px 5px;border-radius:4px;background:' + (p[2] === '纠偏' ? 'var(--crit-bg)' : 'var(--sunken)') + ';color:' + (p[2] === '纠偏' ? 'var(--crit)' : 'var(--ink-2)') + '">' + p[2] + '</span></button>').join('') + '</div><div class="row" style="margin-top:10px;flex-wrap:wrap"><span style="flex:1;min-width:200px;font-size:12px;color:var(--ink-2)">4 条纠偏语可以直接变成规则，让 Agent 先遵守，而不是等你提醒。</span><button type="button" class="btn sm" data-act="phrasesToRule">生成规则草稿</button></div></div>' +
    '<div class="card pad"><div class="hd"><div class="grow"><span class="ct">情绪的前因</span><span class="cap">与会话特征的关联 · 相关不等于因果</span></div></div><div class="col" style="gap:8px">' + DRIVERS.map((d) => { const w = Math.abs(d[1]) / 0.5 * 50; return '<div style="display:grid;grid-template-columns:minmax(0,1fr) 150px 48px;gap:10px;align-items:center;font-size:12px"><span style="color:var(--ink-2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">' + d[0] + '</span><span style="position:relative;height:8px;display:block"><span style="position:absolute;left:50%;top:-3px;width:1px;height:14px;background:var(--line)"></span><span style="position:absolute;top:0;height:8px;left:' + (d[1] < 0 ? 50 - w : 50) + '%;width:' + w + '%;border-radius:' + (d[1] < 0 ? '4px 0 0 4px' : '0 4px 4px 0') + ';background:' + (d[1] < 0 ? 'var(--crit-m)' : 'var(--ink-2)') + '"></span></span><span class="mono" style="text-align:right;font-weight:600">' + (d[1] > 0 ? '+' : '−') + Math.abs(d[1]).toFixed(2) + '</span></div>'; }).join('') + '</div><div class="cap" style="font-size:11px;margin-top:10px">左 = 情绪更差 · 右 = 情绪更好 · 数值为情绪均值差</div></div></div></div></div>';
};
TIPS.mood = (i) => { const b = CUR.mood && CUR.mood[+i]; if (!b) return ''; const r = rng(hash(b.lbl)); const q = b.mood == null ? '' : b.mood > 0.25 ? QUOTES.pos : b.mood < 0 ? QUOTES.neg : QUOTES.mid; return '<div style="display:flex;justify-content:space-between;gap:14px"><b>' + (b.a === b.b ? mdz(b.a) + ' 周' + WD[wd(b.a)] : md(b.a) + ' – ' + md(b.b)) + '</b><b class="mono">' + (b.mood == null ? '—' : (b.mood > 0 ? '+' : '') + b.mood.toFixed(2)) + '</b></div>' + b.n + ' 个会话 · ' + b.corr + ' 次纠偏' + (q ? '\n<span style="opacity:.85">' + q[Math.floor(r() * q.length)] + '</span>' : ''); };
Object.assign(ACT, {
  fricGo: (el) => { S.fric = el.dataset.k; go('sessions'); toast('已筛选出现「' + el.dataset.k + '」的会话'); },
  topicSet: (el) => { S.topic = S.topic === el.dataset.k ? null : el.dataset.k; render(); },
  phrase: (el) => { const xs = sel().filter((s) => s.corr).slice(-3).reverse(); openDD(el, [{ h: '「' + el.dataset.k + '」的出处（最近 3 次）' }].concat(xs.map((s) => ({ t: md(s.d) + ' · ' + s.title, v: s.id }))), (v) => { S.sess.sel = v; S.sess.mode = 'single'; go('sessions'); }); },
  phrasesToRule: () => { S.studio.type = '规则'; S.studio.goal = '把我的高频纠偏写成 AGENTS.md 规则：「直接合并」「别用子代理」「不要改别的文件」「用 Cloudflare 不是 Vercel」。'; S.studio.from = 'A6 高频反馈语'; S.studio.run = null; go('studio'); },
  moodHow: () => openModal(modalHead('情绪如何计算') + '<div class="mb col" style="gap:10px;font-size:13px;line-height:1.6;color:var(--ink-2)"><p style="margin:0">只看你发出的消息，不评判 Agent 的回复。每条消息由本地 Agent 打一个 −1 到 +1 的分，置信度低于 0.6 的不计入。</p><p style="margin:0">每天的值是当天消息分数的加权平均（按消息条数）。纠偏是被判定为「方向修正」或「不满」的消息。</p><p style="margin:0">关闭语义分析后，这一页只保留计数统计。</p></div><div class="mf"><button type="button" class="btn" data-act="openSettings" data-tab="analysis">分析设置</button><button type="button" class="btn p" data-act="closeModal">知道了</button></div>')
});

